package com.payshield.domain;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="ledger_entries") public class LedgerEntry { @Id private UUID id=UUID.randomUUID(); @Column(nullable=false) private UUID paymentId; @Column(nullable=false) private String entryType; @Column(nullable=false) private String account; @Column(nullable=false,precision=19,scale=2) private BigDecimal amount; @Column(nullable=false) private String currency; @Column(nullable=false) private Instant createdAt=Instant.now(); protected LedgerEntry(){} public LedgerEntry(UUID p,String type,String account,BigDecimal amount,String currency){paymentId=p;entryType=type;this.account=account;this.amount=amount;this.currency=currency;} public String getEntryType(){return entryType;} public String getAccount(){return account;} public BigDecimal getAmount(){return amount;} public String getCurrency(){return currency;} public Instant getCreatedAt(){return createdAt;} }
